// buildFinalizeCompactTranscript generates the compact transcript for a single checkpoint
// during turn-end finalization. It reads the checkpoint's transcript start offset and
// dispatches to external compaction, in-process compaction, or skips as appropriate.
func buildFinalizeCompactTranscript(
	ctx context.Context,
	store *checkpoint.GitStore,
	v2Store *checkpoint.V2GitStore,
	v2Only bool,
	cpID id.CheckpointID,
	cpIDStr string,
	state *SessionState,
	redactedTranscript redact.RedactedBytes,
) []byte {
	finalAg, _ := agent.GetByAgentType(state.AgentType) //nolint:errcheck // ag may be nil for unknown agent types; compactTranscriptForV2 handles nil

			slog.String("agent_type", string(state.AgentType)),
		)
		return &ExtractedSessionData{
			FilesTouched: state.FilesTouched,
		}, nil
	}
}

// buildCompactTranscript produces compact (v2) transcript forms when v2
// checkpoints are enabled. The transcript must be pre-redacted. Returns
// the compaction duration for timing logs.
func buildCompactTranscript(ctx context.Context, ag agent.Agent, redacted redact.RedactedBytes, state *SessionState, writeOpts *cpkg.WriteCommittedOptions) time.Duration {
	compactStart := time.Now()
	compactCtx, compactSpan := perf.Start(ctx, "compact_transcript_v2")
	defer compactSpan.End()
	if settings.IsCheckpointsV2Enabled(ctx) {
		if compactor, ok := agent.AsTranscriptCompactor(ag); ok {
			if compacted := compactTranscriptForExternalAgent(compactCtx, compactor, state.SessionID, state.TranscriptPath); compacted != nil {
				writeOpts.CompactTranscript = compacted.Transcript
				writeOpts.CompactTranscriptStart = state.CompactTranscriptStart

	prompts = readPromptsFromFilesystem(ctx, state.SessionID)
}

// Redact secrets before writing. Checkpoint store methods require
// pre-redacted in-memory transcript content from callers. The live
// transcript on disk is still treated as raw/untrusted input, so redact it
// here before anything is persisted to the metadata branch.
//
// On failure: drop the transcript but continue writing checkpoint metadata
// (attribution, files touched, prompts). Hooks run without user interaction
// so there is no retry path — preserving partial metadata is better than
// losing everything. Persisting an unredacted transcript would be worse.
_, redactSpan := perf.Start(logCtx, "redact_transcript")
redactedTranscript, redactErr := redact.JSONLBytes(fullTranscript)
redactSpan.End()
if redactErr != nil {
	logging.Warn(logCtx, "finalize: transcript redaction failed, dropping transcript",
		slog.String("session_id", state.SessionID),
		slog.String("error", redactErr.Error()),
	)

TranscriptPath         string // Path to session transcript file (alternative to in-memory Transcript)
SubagentTranscriptPath string // Path to subagent's transcript file

// Incremental checkpoint fields
IsIncremental       bool   // Whether this is an incremental checkpoint
IncrementalSequence int    // Checkpoint sequence number
IncrementalType     string // Tool type that triggered this checkpoint
IncrementalData     []byte // Tool input payload for this checkpoint

// Commit message fields (used for task checkpoints)
CommitSubject string // Subject line for the metadata commit (overrides default)

// Agent identifies the agent that created this checkpoint (e.g., "Claude Code", "Cursor")
Agent types.AgentType

// Model is the LLM model used during the session (e.g., "claude-sonnet-4-20250514")
Model string

// TurnID correlates checkpoints from the same agent turn.
TurnID string

