// UpdateCommitted replaces the prompts and/or transcript for an existing v2 checkpoint.
// Called at stop time to finalize checkpoints with the complete session transcript.
//
// On /main: replaces prompts and compact transcript (if provided).
// On /full/current: replaces the raw transcript (if provided).
//
// Returns ErrCheckpointNotFound if the checkpoint doesn't exist on /main.
func (s *V2GitStore) UpdateCommitted(ctx context.Context, opts UpdateCommittedOptions) error {
	if opts.CheckpointID.IsEmpty() {
		return errors.New("invalid update options: checkpoint ID is required")
	}

	sessionIndex, err := s.updateCommittedMain(ctx, opts)
	if err != nil {
		return fmt.Errorf("v2 /main update failed: %w", err)
	}

		logging.Warn(ctx, "compact transcript generation failed, skipping transcript.jsonl on /main",
			slog.String("agent", string(ag.Name())),
			slog.String("error", err.Error()),
		)
		return nil
	}
	return compacted
}

// countCompactLines returns line count for compact transcript JSONL.
func countCompactLines(compactTranscript []byte) int {
	return bytes.Count(compactTranscript, []byte{'\n'})
}

// computeCompactTranscriptStart chooses the compact transcript start line offset
// for v2 /main metadata.
//
// Preferred source is session state CompactTranscriptStart. For legacy sessions
// that have only full-transcript offsets persisted, this recalculates the compact
// offset from transcript bytes when possible. On any failure, returns 0 (fail-open).

result, err := s.CondenseSession(ctx, repo, checkpointID, state, committedFiles, opts...)
if err != nil {
	logging.Warn(logCtx, "condensation failed",
		slog.String("session_id", state.SessionID),
		slog.String("error", err.Error()),
	)
	return false
}

if result.Skipped {
	logging.Debug(logCtx, "condensation skipped, session state unchanged",
		slog.String("session_id", state.SessionID),
		slog.String("checkpoint_id", checkpointID.String()),
	)
	return false
}

